reference_solution:
def exist(board, word):
    R, C = len(board), len(board[0]) if board else 0
    def dfs(r, c, i):
        if i == len(word):
            return True
        if r < 0 or c < 0 or r >= R or c >= C or board[r][c] != word[i]:
            return False
        tmp = board[r][c]
        board[r][c] = '#'
        ok = dfs(r + 1, c, i + 1) or dfs(r - 1, c, i + 1) or dfs(r, c + 1, i + 1) or dfs(r, c - 1, i + 1)
        board[r][c] = tmp
        return ok
    return any(dfs(r, c, 0) for r in range(R) for c in range(C))

brute_force_solution:
def exist(board, word):
    R, C = len(board), len(board[0]) if board else 0
    def go(r, c, i, seen):
        if board[r][c] != word[i]:
            return False
        if i == len(word) - 1:
            return True
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in seen and go(nr, nc, i + 1, seen | {(nr, nc)}):
                return True
        return False
    return any(go(r, c, 0, {(r, c)}) for r in range(R) for c in range(C))

